"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["49050"],{53712(e){e.exports=JSON.parse('{"id":"FIN-833","slug":"debt-consolidation","term":"Debt Consolidation","also_known_as":[],"difficulty":"Beginner","definition":"Debt consolidation is combining several debts into a single new loan or payment, often with the aim of lowering the interest rate, reducing monthly payments or simplifying repayment.","explanation":["People with multiple debts, such as several credit cards, store cards and personal loans, may find it hard to keep track of payments and may be paying high interest rates. Consolidating replaces these with one debt.","Common methods include taking out a debt consolidation loan from a bank, using a balance transfer credit card with a low introductory rate, borrowing against home equity or entering a formal debt management plan through a debt advice organisation.","For example, someone with three credit cards charging around 25% interest might take out a personal loan at 10% to pay them all off, leaving them with one lower monthly payment and less interest overall.","Debt consolidation can help, but it is not a solution in itself. Spreading debt over a longer period can lower monthly payments while increasing the total interest paid. Securing unsecured debts against a home puts the home at risk. And consolidation only works if the borrower avoids building up new debts on the cleared credit cards. Independent debt advice can help people find the best option."],"note":"","total":1500,"prev":{"slug":"debt-collector","term":"Debt Collector"},"next":{"slug":"debt-free-cash-free","term":"Debt-Free Cash-Free"}}')}}]);